//! Vendored libraries and bundler output (JavaScript) are skipped as `vendored` with
//! `skip_generated`, and counted in the scan statistics.

mod common;

use common::fake_plugin::FakePlugin;
use common::{opts, write};
use mote_engine::analyze::SkipReason;
use mote_engine::result::FileStatus;
use mote_engine::scan::{Scanner, SourceSpec};
use mote_engine::{Config, Registry};
use std::path::Path;
use std::sync::Arc;

/// A scanner whose fake plugin handles `.js` files.
fn js_scanner(root: &Path, yaml: &str) -> Scanner {
    let mut p = FakePlugin::new("fk");
    p.exts = &["js"];
    let registry = Arc::new(Registry::new(vec![Box::new(p)]).expect("registry"));
    Scanner::new(registry, Config::from_yaml_str(yaml).expect("config"), root).expect("scanner")
}

#[test]
fn vendored_javascript_is_skipped_and_counted() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    write(
        root,
        "public/js/jquery.cookie.js",
        "/*!\n * jQuery Cookie Plugin v1.4.1\n * Copyright 2013 Klaus Hartl\n * Released under the MIT license\n */\nLOUD\n",
    );
    write(
        root,
        "static/main.js",
        "/******/ (() => { // webpackBootstrap\n/******/ \tvar __webpack_modules__ = ({});\nLOUD\n/******/ })();\n",
    );
    // First-party code: compiled output with a source map, a header comment without a release.
    write(
        root,
        "build/install.js",
        "\"use strict\";\nObject.defineProperty(exports, \"__esModule\", { value: true });\nLOUD\n//# sourceMappingURL=install.js.map\n",
    );
    write(
        root,
        "src/app.js",
        "/*!\n * Module dependencies.\n */\nLOUD\n",
    );
    let s = js_scanner(root, "");
    let r = s.scan(&opts(SourceSpec::Directory, None)).unwrap();
    let files: Vec<(&str, Option<SkipReason>)> = r
        .files
        .iter()
        .map(|f| (f.path.as_str(), f.skip_reason))
        .collect();
    assert_eq!(
        files,
        vec![
            ("build/install.js", None),
            ("public/js/jquery.cookie.js", Some(SkipReason::Vendored)),
            ("src/app.js", None),
            ("static/main.js", Some(SkipReason::Vendored)),
        ]
    );
    assert_eq!(r.stats.skipped_by_reason.get("vendored"), Some(&2));
    assert_eq!(r.findings.len(), 2);

    // `skip_generated: false` analyzes them like any file.
    let s = js_scanner(root, "skip_generated: false\n");
    let r = s.scan(&opts(SourceSpec::Directory, None)).unwrap();
    assert!(r.files.iter().all(|f| f.skip_reason.is_none()));
    assert_eq!(r.findings.len(), 4);
}

/// Each file's skip reason and status.
fn outcome(r: &mote_engine::ScanResult) -> Vec<(String, Option<SkipReason>, FileStatus)> {
    r.files
        .iter()
        .map(|f| (f.path.clone(), f.skip_reason, f.status))
        .collect()
}

#[test]
fn skip_generated_except_analyzes_files_that_look_generated() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    let cache = tempfile::tempdir().unwrap();
    let banner = "/*!\n * jQuery Cookie Plugin v1.4.1\n * Copyright 2013 Klaus Hartl\n * Released under the MIT license\n */\nLOUD\n";
    write(root, "public/js/jquery.cookie.js", banner);
    write(root, "public/js/excluded.js", banner);
    write(
        root,
        "src/gen.js",
        "// Code generated by protoc. DO NOT EDIT.\nLOUD\n",
    );
    write(root, "src/min.js", &format!("LOUD;{}\n", "x".repeat(6000)));
    write(root, ".yarn/plugins/plugin.js", "LOUD\n");
    write(root, "src/app.js", "LOUD\n");
    let base = "exclude: [\"public/js/excluded.js\"]\n";
    let excepted =
        format!("{base}skip_generated_except: [\"public/js\", \"src/gen.js\", \"*.min.js\", \"src/min.js\", \".yarn/**\"]\n");
    use FileStatus::{Analyzed, Cached, Skipped};
    let skipped = |status| {
        vec![
            (
                ".yarn/plugins/plugin.js".to_string(),
                Some(SkipReason::Generated),
                Skipped,
            ),
            (
                "public/js/excluded.js".into(),
                Some(SkipReason::Excluded),
                Skipped,
            ),
            (
                "public/js/jquery.cookie.js".into(),
                Some(SkipReason::Vendored),
                Skipped,
            ),
            ("src/app.js".into(), None, status),
            ("src/gen.js".into(), Some(SkipReason::Generated), Skipped),
            ("src/min.js".into(), Some(SkipReason::Minified), Skipped),
        ]
    };
    let r = js_scanner(root, base)
        .scan(&opts(SourceSpec::Directory, Some(cache.path())))
        .unwrap();
    assert_eq!(outcome(&r), skipped(Analyzed));

    // Excepted files are analyzed; `exclude` still wins. Only the files whose status changes
    // are analyzed again: the others keep their cache entries.
    let r = js_scanner(root, &excepted)
        .scan(&opts(SourceSpec::Directory, Some(cache.path())))
        .unwrap();
    assert_eq!(
        outcome(&r),
        vec![
            (".yarn/plugins/plugin.js".to_string(), None, Analyzed),
            (
                "public/js/excluded.js".into(),
                Some(SkipReason::Excluded),
                Skipped
            ),
            ("public/js/jquery.cookie.js".into(), None, Analyzed),
            ("src/app.js".into(), None, Cached),
            ("src/gen.js".into(), None, Analyzed),
            ("src/min.js".into(), None, Analyzed),
        ]
    );
    assert_eq!(r.findings.len(), 5);
    // The same outcomes as `skip_generated: false` for those files, which share its cache
    // entries (`src/app.js` was only analyzed with the checks so far).
    let r = js_scanner(root, &format!("{base}skip_generated: false\n"))
        .scan(&opts(SourceSpec::Directory, Some(cache.path())))
        .unwrap();
    let statuses: Vec<(&str, FileStatus)> = r
        .files
        .iter()
        .map(|f| (f.path.as_str(), f.status))
        .collect();
    assert_eq!(
        statuses,
        vec![
            (".yarn/plugins/plugin.js", Cached),
            ("public/js/excluded.js", Skipped),
            ("public/js/jquery.cookie.js", Cached),
            ("src/app.js", Analyzed),
            ("src/gen.js", Cached),
            ("src/min.js", Cached),
        ]
    );
    // Back to the plain configuration: every outcome comes from the cache.
    let r = js_scanner(root, base)
        .scan(&opts(SourceSpec::Directory, Some(cache.path())))
        .unwrap();
    assert_eq!(outcome(&r), skipped(Cached));

    // Invalid globs are configuration errors.
    let reg = Arc::new(Registry::new(vec![Box::new(FakePlugin::new("fk"))]).unwrap());
    let e = Scanner::new(
        reg,
        Config::from_yaml_str("skip_generated_except: [\"src/[\"]\n").unwrap(),
        root,
    )
    .unwrap_err();
    assert!(e.to_string().contains("skip_generated_except"), "{e}");
}

/// A UMD bundle with a source map under `banner`, like socket.io's committed `client-dist`.
fn umd_bundle(banner: &str) -> String {
    let body: String = (0..60)
        .map(|i| format!("    var value{i} = compute({i}, \"text\") / 2;\n"))
        .collect();
    format!(
        "{banner}(function (global, factory) {{\n  typeof exports === 'object' ? module.exports = factory() : global.io = factory();\n}})(this, (function () {{ 'use strict';\nLOUD\n{body}  return lookup;\n}}));\n//# sourceMappingURL=socket.io.js.map\n"
    )
}

#[test]
fn a_banner_naming_the_projects_package_is_not_vendored() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    let cache = tempfile::tempdir().unwrap();
    write(
        root,
        "package.json",
        "{\"name\": \"@acme/mylib\", \"version\": \"1.2.3\"}\n",
    );
    write(
        root,
        "src/mylib.js",
        "/*! MyLib v1.2.3 | (c) Acme | MIT */\nLOUD\n",
    );
    write(
        root,
        "public/js/jquery.cookie.js",
        "/*!\n * jQuery Cookie Plugin v1.4.1\n * Copyright 2013 Klaus Hartl\n * Released under the MIT license\n */\nLOUD\n",
    );
    let socket_banner = "/*!\n * Socket.IO v4.8.4\n * (c) 2014-2026 Guillermo Rauch\n * Released under the MIT License.\n */\n";
    write(
        root,
        "packages/socket.io/package.json",
        "{\"name\": \"socket.io\"}\n",
    );
    write(
        root,
        "packages/socket.io/lib/index.js",
        &format!("{socket_banner}LOUD\n"),
    );
    write(
        root,
        "packages/socket.io/client-dist/socket.io.js",
        &umd_bundle(socket_banner),
    );
    let scan = || {
        js_scanner(root, "")
            .scan(&opts(SourceSpec::Directory, Some(cache.path())))
            .unwrap()
    };
    use FileStatus::{Analyzed, Cached, Skipped};
    let r = scan();
    assert_eq!(
        outcome(&r),
        vec![
            // The package's own build output stays skipped: one wrapper with a source map.
            (
                "packages/socket.io/client-dist/socket.io.js".to_string(),
                Some(SkipReason::Vendored),
                Skipped
            ),
            // The package's own source (nearest package.json) and the root package's.
            ("packages/socket.io/lib/index.js".into(), None, Analyzed),
            (
                "public/js/jquery.cookie.js".into(),
                Some(SkipReason::Vendored),
                Skipped
            ),
            ("src/mylib.js".into(), None, Analyzed),
        ]
    );
    // Renaming the package is noticed although the file did not change.
    write(root, "package.json", "{\"name\": \"app\"}\n");
    let r = scan();
    assert_eq!(
        outcome(&r),
        vec![
            (
                "packages/socket.io/client-dist/socket.io.js".to_string(),
                Some(SkipReason::Vendored),
                Skipped
            ),
            ("packages/socket.io/lib/index.js".into(), None, Analyzed),
            (
                "public/js/jquery.cookie.js".into(),
                Some(SkipReason::Vendored),
                Skipped
            ),
            ("src/mylib.js".into(), Some(SkipReason::Vendored), Skipped),
        ]
    );
    let r = scan();
    assert!(
        r.files.iter().all(|f| f.status
            == if f.skip_reason.is_some() {
                Skipped
            } else {
                Cached
            }),
        "{:?}",
        outcome(&r)
    );
}
